SELECT bm_cargo_position.id,CONCAT(GROUP_CONCAT(bm_storage.name SEPARATOR #{sp}),#{sp},bm_cargo_position.position) AS cargoPath FROM bm_cargo_position, bm_storage WHERE FIND_IN_SET(bm_storage.id, bm_cargo_position.id_path) and bm_cargo_position.id in
#{positionId}
GROUP BY bm_cargo_position.id
